fn has_only_one_distinct_element(arr: &Vec<i32>) -> bool {
    // An empty array or a single-element array trivially has only one distinct element.
    if arr.len() <= 1 {
        return true;
    }

    // Grab the first element and compare all subsequent elements against it.
    let first = arr[0];
    for &x in &arr[1..] {
        if x != first {
            return false;
        }
    }

    true
}

